#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; bool isEnd = false; };

class WordDictionary {
public:
    TrieNode* root = new TrieNode();

    void addWord(string word) {
        TrieNode* node = root;
        for (char c : word) {
            if (!node->children.count(c)) node->children[c] = new TrieNode();
            node = node->children[c];
        }
        node->isEnd = true;
    }

    bool search(string word) {
        return dfs(root, word, 0);
    }

    bool dfs(TrieNode* node, const string& word, int i) {
        if (i == (int)word.size()) return node->isEnd;
        char c = word[i];
        if (c == '.') {
            for (auto& [ch, child] : node->children) {                     // branch into ALL children
                if (dfs(child, word, i + 1)) return true;
            }
            return false;
        }
        if (!node->children.count(c)) return false;
        return dfs(node->children[c], word, i + 1);
    }
};
